@page "/dashboard"
@using sv_c05ab085c0fd4fa6bb20da7b7b09aee7.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">@Warehouse?.Name</p>
    </div>
</div>

<div class="card mb-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            <span class="fs-1 fw-bold text-danger">@AlertService.CurrentAlertCount</span>
            <span class="text-muted ms-2">items below minimum level</span>
        </p>
        <p class="text-muted small mb-0">Refreshes every 10 seconds</p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;

        if (Warehouse is not null)
            AlertService.StartPolling(Warehouse.Id);
    }

    protected override void OnParametersSet()
    {
        // Restart polling when the cascaded warehouse changes.
        if (Warehouse is not null)
            AlertService.StartPolling(Warehouse.Id);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
        AlertService.StopPolling();
    }
}

